        "volunteer": (tasks, 1), "giver": (paid, 1), "quiz_first": (qs["taken"], 1), "quiz_full": (full, 1),
        "quiz_4": (qs["current"], 4), "inviter": (invited, 1), "friends_5": (friends, 5),
    }
    out = []
    for b in BADGES:
