        "quiz_4": (qs["current"], 4), "inviter": (invited, 1), "friends_5": (friends, 5),
    }
    out = []
    for b in BADGES:
        got = have[b[0]]
        out.append({"code": b[0], "title": b[1], "icon": b[2], "how": b[3], "earned": got[0] >= got[1],
